function srtParseTime(s){
  var m=String(s).trim().match(/^(\d{1,2}):(\d{2}):(\d{2})[,.](\d{1,3})$/);
  if(!m) return null;
  return ((+m[1])*3600 + (+m[2])*60 + (+m[3]))*1000 + Number((m[4]+'00').slice(0,3));
}
function srtFmtTime(ms, vtt){
  if(ms<0) ms=0;
  var h=Math.floor(ms/3600000), mi=Math.floor(ms%3600000/60000), se=Math.floor(ms%60000/1000), mss=ms%1000;
  function p(n,w){ n=String(n); while(n.length<w) n='0'+n; return n; }
  return p(h,2)+':'+p(mi,2)+':'+p(se,2)+(vtt?'.':',')+p(mss,3);
}
function srtParse(text){
  if(!text || !String(text).trim()) return { error:'请输入字幕内容' };
  var body=String(text).replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').replace(/^WEBVTT[^\n]*\n+/,'');
  var blocks=body.split(/\n{2,}/), cues=[], bad=[];
  for(var i=0;i<blocks.length;i++){
    var lines=blocks[i].split('\n').filter(function(l){ return l.trim()!==''; });
    if(!lines.length) continue;
    if(/^\d+$/.test(lines[0].trim()) && lines.length>1) lines.shift();
    var tm=lines[0] && lines[0].match(/(\S+)\s*-->\s*(\S+)/);
    if(!tm){ bad.push(i+1); continue; }
    var a=srtParseTime(tm[1]), b=srtParseTime(tm[2]);
    if(a===null||b===null){ bad.push(i+1); continue; }
    cues.push({ start:a, end:b, text:lines.slice(1).join('\n') });
  }
  if(!cues.length) return { error:'未解析到有效字幕块' };
  return { error:null, cues:cues, bad:bad };
}
function srtShift(cues, deltaMs){
  return cues.map(function(c){
    return { start:Math.max(0,c.start+deltaMs), end:Math.max(0,c.end+deltaMs), text:c.text };
  });
}
function srtScale(cues, factor){
  if(!(factor>0)) return cues;
  return cues.map(function(c){
    return { start:Math.round(c.start*factor), end:Math.round(c.end*factor), text:c.text };
  });
}
function srtStringify(cues, vtt){
  var out = vtt ? 'WEBVTT\n\n' : '';
  for(var i=0;i<cues.length;i++){
    var c=cues[i];
    if(!vtt) out += (i+1)+'\n';
    out += srtFmtTime(c.start,vtt)+' --> '+srtFmtTime(c.end,vtt)+'\n'+c.text+'\n\n';
  }
  return out.replace(/\n+$/,'\n');
}
function srtStats(cues){
  var dur=0, chars=0, overlap=0;
  for(var i=0;i<cues.length;i++){
    dur += Math.max(0, cues[i].end-cues[i].start);
    chars += cues[i].text.replace(/\s/g,'').length;
    if(i && cues[i].start < cues[i-1].end) overlap++;
  }
  return { count:cues.length, duration:dur, chars:chars, overlap:overlap,
           span: cues.length? cues[cues.length-1].end - cues[0].start : 0 };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { srtParseTime:srtParseTime, srtFmtTime:srtFmtTime, srtParse:srtParse,
                     srtShift:srtShift, srtScale:srtScale, srtStringify:srtStringify, srtStats:srtStats };
}
if (typeof window !== 'undefined') {
  window.SrtForgePure = { srtParseTime:srtParseTime, srtFmtTime:srtFmtTime, srtParse:srtParse,
                     srtShift:srtShift, srtScale:srtScale, srtStringify:srtStringify, srtStats:srtStats };
}
